-- Additive customer-support CMS; existing accounts and content are preserved.
begin;
create table if not exists public.ieb_support_content (
  id text primary key default gen_random_uuid()::text,
  kind text not null check (kind in ('notice','faq','settings')),
  translations jsonb not null check (jsonb_typeof(translations)='object' and jsonb_typeof(translations->'ko')='object' and octet_length(translations::text)<=100000),
  contact_email text not null default '' check (char_length(contact_email)<=254 and contact_email !~ E'[\r\n]'),
  notice_date date,
  display_order integer not null default 0 check (display_order between 0 and 10000),
  published boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((kind='notice' and notice_date is not null) or (kind<>'notice' and notice_date is null)),
  check (kind<>'settings' or (id='support-settings' and published=true))
);
create unique index if not exists ieb_support_settings_unique on public.ieb_support_content(kind) where kind='settings';
create index if not exists ieb_support_order_idx on public.ieb_support_content(kind,display_order,notice_date,id);
alter table public.ieb_support_content enable row level security;
revoke all on public.ieb_support_content from anon, authenticated;
grant select on public.ieb_support_content to anon, authenticated;
grant all on public.ieb_support_content to service_role;
drop policy if exists support_published_read on public.ieb_support_content;
create policy support_published_read on public.ieb_support_content for select to anon, authenticated using (published);
create or replace function ieb_private.touch_support_updated_at() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=clock_timestamp();return new;end;$$;
revoke all on function ieb_private.touch_support_updated_at() from public, anon, authenticated;
grant execute on function ieb_private.touch_support_updated_at() to service_role;
drop trigger if exists ieb_touch_support_updated_at on public.ieb_support_content;
create trigger ieb_touch_support_updated_at before update on public.ieb_support_content for each row execute function ieb_private.touch_support_updated_at();

insert into public.ieb_support_content(id,kind,translations,notice_date,display_order,published,contact_email)
select id,kind,translations,notice_date,display_order,published,contact_email
from jsonb_to_recordset($support_seed$[{"id":"notice-seed-0","kind":"notice","translations":{"ko":{"title":"I EAT BUSAN 1.0 출시 안내","body":"부산 향토 음식 20가지의 정보, 먹는 방법, 알레르기 정보, 식당 리스트를 한국어·영어·중국어·일본어로 볼 수 있어요."},"en":{"title":"I EAT BUSAN 1.0 is here","body":"Explore 20 Busan dishes with details, how to eat, allergens and restaurants in Korean, English, Chinese and Japanese."},"zh":{"title":"I EAT BUSAN 1.0 正式上线","body":"可用韩语、英语、中文、日语查看 20 种釜山美食的介绍、吃法、过敏原和餐厅信息。"},"ja":{"title":"I EAT BUSAN 1.0 リリース","body":"釜山の郷土料理20品の情報・食べ方・アレルギー・お店リストを、韓国語・英語・中国語・日本語で見られます。"}},"notice_date":"2026-11-03","display_order":0,"published":true,"contact_email":""},{"id":"notice-seed-1","kind":"notice","translations":{"ko":{"title":"커뮤니티 이용 수칙","body":"광고·도배·비방 글은 예고 없이 삭제될 수 있어요. 서로 존중하는 커뮤니티를 함께 만들어 주세요."},"en":{"title":"Community guidelines","body":"Ads, spam and abusive posts may be removed without notice. Please be respectful."},"zh":{"title":"社区守则","body":"广告、刷屏和恶意帖子可能会被直接删除，请相互尊重。"},"ja":{"title":"コミュニティガイドライン","body":"広告・連投・誹謗中傷の投稿は予告なく削除される場合があります。お互いを尊重しましょう。"}},"notice_date":"2026-11-01","display_order":1,"published":true,"contact_email":""},{"id":"faq-seed-0","kind":"faq","translations":{"ko":{"title":"식당 정보는 정확한가요?","body":"식당 이름과 위치는 공개된 자료를 바탕으로 정리했지만, 영업시간과 가격은 바뀔 수 있어요. 방문 전 지도 앱에서 꼭 확인해 주세요."},"en":{"title":"Is the restaurant info accurate?","body":"Names and areas come from public sources, but hours and prices can change. Please check a map app before visiting."},"zh":{"title":"餐厅信息准确吗？","body":"餐厅名称和位置来自公开资料，但营业时间和价格可能变动，出发前请在地图应用中确认。"},"ja":{"title":"お店の情報は正確ですか？","body":"店名と場所は公開資料をもとにしていますが、営業時間や価格は変わることがあります。お出かけ前に地図アプリでご確認ください。"}},"notice_date":null,"display_order":0,"published":true,"contact_email":""},{"id":"faq-seed-1","kind":"faq","translations":{"ko":{"title":"알레르기 정보는 믿을 수 있나요?","body":"일반적인 조리법 기준의 안내예요. 식당마다 재료가 다를 수 있으니 주문할 때 직접 확인해 주세요."},"en":{"title":"Can I rely on the allergen info?","body":"It reflects typical recipes. Ingredients vary by restaurant, so please confirm when ordering."},"zh":{"title":"过敏原信息可靠吗？","body":"这是按一般做法整理的参考信息，各家餐厅用料不同，点餐时请直接确认。"},"ja":{"title":"アレルギー情報は信頼できますか？","body":"一般的なレシピに基づく目安です。お店によって材料が異なるため、注文時にご確認ください。"}},"notice_date":null,"display_order":1,"published":true,"contact_email":""},{"id":"faq-seed-2","kind":"faq","translations":{"ko":{"title":"언어는 어떻게 바꾸나요?","body":"홈 화면 위쪽의 언어 버튼이나 마이 > 설정 > 언어에서 바꿀 수 있어요."},"en":{"title":"How do I change the language?","body":"Use the language button at the top of Home, or Account > Settings > Language."},"zh":{"title":"如何切换语言？","body":"可通过首页上方的语言按钮，或 我的 > 设置 > 语言 切换。"},"ja":{"title":"言語はどう変えますか？","body":"ホーム上部の言語ボタン、または マイページ > 設定 > 言語 から変更できます。"}},"notice_date":null,"display_order":2,"published":true,"contact_email":""},{"id":"faq-seed-3","kind":"faq","translations":{"ko":{"title":"내 글은 어디에 저장되나요?","body":"로그인 후 작성한 글·댓글·사진은 서버에 저장돼요. 다른 기기에서도 같은 계정으로 볼 수 있고, 브라우저 데이터를 지워도 삭제되지 않아요."},"en":{"title":"Where are my posts stored?","body":"Posts, comments and photos you add while logged in are stored on the server. You can access them with the same account on another device. Clearing browser data does not delete them."},"zh":{"title":"我的帖子保存在哪里？","body":"登录后发布的帖子、评论和照片保存在服务器上，使用同一账号可在其他设备查看。清除浏览器数据不会删除这些内容。"},"ja":{"title":"自分の投稿はどこに保存されますか？","body":"ログインして投稿した記事・コメント・写真はサーバーに保存されます。同じアカウントで別の端末からも閲覧できます。ブラウザーのデータを消去しても削除されません。"}},"notice_date":null,"display_order":3,"published":true,"contact_email":""},{"id":"support-settings","kind":"settings","translations":{"ko":{"sectionTitle":"고객 지원","noticesLabel":"공지사항","faqLabel":"자주 묻는 질문","contactLabel":"고객센터","noticesTitle":"공지사항","faqTitle":"자주 묻는 질문","contactTitle":"고객센터","contactDescription":"문의용 이메일은 아직 준비 중이에요. 아래 주소는 시안용 예시이며 메일을 받을 수 없어요."},"en":{"sectionTitle":"Support","noticesLabel":"Notices","faqLabel":"FAQ","contactLabel":"Contact us","noticesTitle":"Notices","faqTitle":"FAQ","contactTitle":"Contact us","contactDescription":"Our contact email is not set up yet. The address below is a placeholder and cannot receive messages."},"zh":{"sectionTitle":"客户支持","noticesLabel":"公告","faqLabel":"常见问题","contactLabel":"联系我们","noticesTitle":"公告","faqTitle":"常见问题","contactTitle":"联系我们","contactDescription":"联系邮箱尚未开通。以下地址仅为示例，无法接收邮件。"},"ja":{"sectionTitle":"サポート","noticesLabel":"お知らせ","faqLabel":"よくある質問","contactLabel":"お問い合わせ","noticesTitle":"お知らせ","faqTitle":"よくある質問","contactTitle":"お問い合わせ","contactDescription":"お問い合わせ用のメールアドレスは準備中です。以下はサンプルのため、メールを受信できません。"}},"notice_date":null,"display_order":0,"published":true,"contact_email":"help@ieatbusan.example"}]$support_seed$::jsonb) as x(id text,kind text,translations jsonb,notice_date date,display_order integer,published boolean,contact_email text)
on conflict (id) do nothing;
commit;
